import * as T from '../three.module.min.js';
import {EVENTS,moveBoat} from './model.mjs';
import {missionMerge} from './adventure.mjs';
const mat=c=>new T.MeshStandardMaterial({color:c,roughness:.6});
function add(g,geo,c,x=0,y=0,z=0){const m=new T.Mesh(geo,mat(c));m.position.set(x,y,z);g.add(m);return m;}
function ring(g,r,c){const m=add(g,new T.TorusGeometry(r,.035,5,36),c);m.rotation.x=-Math.PI/2;return m;}
function croc(g){const root=new T.Group();g.add(root);const body=add(root,new T.SphereGeometry(.7,10,7),'#598563',0,.15,0);body.scale.set(1,.45,2);add(root,new T.BoxGeometry(.85,.28,1.9),'#83a66d',0,.18,1.75);for(const x of [-.3,.3]){add(root,new T.SphereGeometry(.12,7,5),'#efcc70',x,.42,1.25);add(root,new T.SphereGeometry(.05,6,5),'#052a35',x,.48,1.31);}const tail=add(root,new T.ConeGeometry(.5,2,6),'#497255',0,0,-2);tail.rotation.x=-Math.PI/2;return root;}
function mascot(){const g=new T.Group();const h=add(g,new T.SphereGeometry(.68,18,12),'#ff602b',0,.7,0);h.scale.y=.92;for(const x of [-.28,.28]){const eye=add(g,new T.SphereGeometry(.25,12,8),'#061c34',x,.84,.54);eye.scale.set(1,.65,.25);}add(g,new T.BoxGeometry(.18,.07,.1),'#061c34',0,.86,.68);const hat=add(g,new T.ConeGeometry(.48,.45,12),'#263caa',0,1.46,0);hat.rotation.z=.2;const smile=add(g,new T.TorusGeometry(.28,.045,6,20,Math.PI),'#fff0ce',0,.49,.56);smile.rotation.z=Math.PI;return g;}
export class LivingSea{
 constructor(world){this.w=world;this.group=new T.Group();world.world.add(this.group);this.state='lost';this.time=0;this.boarding=0;this.diving=0;this.mascot=mascot();this.group.add(this.mascot);this.mascot.position.set(11,0,-40);this.crocs=Array.from({length:3},()=>croc(this.group));this.ripples=Array.from({length:8},()=>ring(this.group,.3,'#a9f3ed'));this.woods=Array.from({length:42},(_,i)=>{const g=new T.Group();this.group.add(g);for(let k=0;k<3;k++){const m=add(g,new T.BoxGeometry(.28,.18,1.7),'#bc986d',(k-1)*.37,0,Math.sin(k)*.35);m.rotation.y=k*.23;}ring(g,.95,'#d4c191');const f={mesh:g,cooldown:0};this.place(f,i);return f;});this.chest=new T.Group();this.group.add(this.chest);add(this.chest,new T.BoxGeometry(1.5,.85,1),'#b97b39',0,.42);for(const x of [-.55,.55])add(this.chest,new T.BoxGeometry(.12,.92,1.06),'#ffde89',x,.44);ring(this.chest,2,'#ffe6aa');this.chest.visible=false;this.chestAt=18;this.chestUntil=0;
 this.dolphin=new T.Group();this.group.add(this.dolphin);const body=add(this.dolphin,new T.SphereGeometry(.6,12,10),'#a8d1d6');body.scale.set(.6,.7,2.3);const fin=add(this.dolphin,new T.ConeGeometry(.4,.9,3),'#78b6c3',0,.6,-.2);fin.rotation.y=Math.PI/2;add(this.dolphin,new T.ConeGeometry(.19,.8,8),'#a8d1d6',0,.05,1.5).rotation.x=Math.PI/2;for(const x of [-1,1]){const f=add(this.dolphin,new T.ConeGeometry(.24,.85,3),'#78b6c3',x*.45,-.07,-.3);f.rotation.z=x*1.2;}this.dolphin.visible=false;this.dolphinAt=35;this.dolphinLife=0;this.follow=0;
 this.vortex=new T.Group();this.vortex.position.set(-25,.04,-167);this.group.add(this.vortex);for(let i=0;i<9;i++){const r=ring(this.vortex,1+i*.42,i%2?'#79d0d6':'#246d9b');r.position.y=i*.007;r.scale.x=.84;}this.vortexCharge=0;this.vortexCooldown=0;
 }
 emit(type,extra={}){this.w.onLife?.({type,...extra});}
 place(f,i=Math.random()*42){let x=-60+Math.random()*99,z=38-Math.random()*282;if(i<6){x=-5+i*2;z=22-i*7;}const s={x,z,heading:0,vx:0,vz:0};moveBoat(s,{},0);f.mesh.position.set(s.x,.15,s.z);f.mesh.rotation.y=Math.random()*6;f.mesh.visible=true;}
 setProgress(p,reset=false){const next=reset?missionMerge('lost',p.mission):missionMerge(this.state,p.mission);if(next!==this.state){this.state=next;this.boarding=0;}this.syncMascot();}
 syncMascot(){if(this.boarding)return;if(this.state==='lost'){if(this.mascot.parent!==this.group)this.group.add(this.mascot);this.mascot.position.set(11,.2,-40);this.mascot.scale.setScalar(1);this.diving=0;}else if(this.state==='aboard'){if(this.mascot.parent!==this.w.boat.g)this.w.boat.g.add(this.mascot);this.mascot.position.set(0,.62,.9);this.mascot.scale.setScalar(.7);this.mascot.rotation.set(0,0,0);}else if(this.state==='delivered'){if(this.mascot.parent!==this.group)this.group.add(this.mascot);this.mascot.scale.setScalar(1);this.mascot.position.set(-20,2,-230);}}
 rescue(){if(this.state!=='lost'||Math.hypot(this.w.s.x-11,this.w.s.z+40)>13)return;this.state='aboard';this.boarding=1.25;this.from=this.mascot.position.clone();this.emit('rescued');}
 tick(dt,t,active){this.time+=active?dt:0;const s=this.w.s,near=Math.hypot(s.x-11,s.z+40);if(near<13)this.diving=Math.min(1,this.diving+dt*.6);else if(this.state==='lost')this.diving=Math.max(0,this.diving-dt*.15);this.crocs.forEach((g,i)=>{const a=t*.22+i*Math.PI*2/3;g.position.set(11+Math.cos(a)*4,-this.diving*3,-40+Math.sin(a)*4);g.rotation.y=-a;g.visible=this.state==='lost'&&this.diving<1;});this.ripples.forEach((g,i)=>{const a=i*2.4,phase=(t*.7+i*.2)%1;g.position.set(11+Math.cos(a)*4,.05,-40+Math.sin(a)*4);g.scale.setScalar(.5+phase*3);g.visible=this.diving>0&&this.diving<1;});
 if(this.state==='lost'){this.mascot.position.y=.2+Math.sin(t*2)*.12;this.mascot.rotation.y=Math.atan2(s.x-11,s.z+40);}else if(this.boarding>0){this.boarding=Math.max(0,this.boarding-dt);const u=1-this.boarding/1.25;this.mascot.position.lerpVectors(this.from,new T.Vector3(s.x,.9,s.z),u);this.mascot.position.y+=Math.sin(u*Math.PI)*3;if(!this.boarding)this.syncMascot();}else if(this.state==='aboard'&&active&&Math.hypot(s.x+24,s.z+241)<30){this.state='delivered';this.boarding=1.25;const pos=new T.Vector3();this.mascot.getWorldPosition(pos);this.group.attach(this.mascot);this.from=pos;this.emit('delivered');}else if(this.state==='delivered'){this.mascot.rotation.y=t*.4;this.mascot.position.y=2+Math.abs(Math.sin(t*3))*.25;}
 // Delivery follows its own arc to land, never leaves the passenger attached to the boat.
 if(this.state==='delivered'&&this.boarding>0){const u=1-this.boarding/1.25;this.mascot.position.lerpVectors(this.from,new T.Vector3(-20,2,-230),u);this.mascot.position.y+=Math.sin(u*Math.PI)*4;}
 if(!active)return;for(const f of this.woods){if(f.cooldown>0){f.cooldown-=dt;if(f.cooldown<=0)this.place(f);continue;}f.mesh.position.y=.15+Math.sin(t*2+f.mesh.position.x)*.07;if(Math.hypot(s.x-f.mesh.position.x,s.z-f.mesh.position.z)<2.4){f.cooldown=55;f.mesh.visible=false;this.emit('find',{kind:'wood',amount:1});}}
 if(!this.chest.visible&&this.time>this.chestAt){const f={mesh:this.chest};this.place(f,30);this.chestUntil=this.time+28;this.emit('chest-spawn',{x:this.chest.position.x,z:this.chest.position.z});}if(this.chest.visible){this.chest.rotation.y=Math.sin(t)*.08;this.chest.children.at(-1).scale.setScalar(.85+.12*Math.sin(t*3));if(Math.hypot(s.x-this.chest.position.x,s.z-this.chest.position.z)<2.7){this.emit('find',{kind:'chest',amount:1,rare:Math.random()<.14});this.chest.visible=false;this.chestAt=this.time+55;}else if(this.time>this.chestUntil){this.chest.visible=false;this.chestAt=this.time+40;}}
 if(!this.dolphin.visible&&this.time>this.dolphinAt){this.dolphin.visible=true;this.dolphinLife=25;this.follow=0;this.dolphin.position.set(s.x-4,0,s.z-5);}if(this.dolphin.visible){this.dolphinLife-=dt;this.dolphin.position.z-=dt*5;this.dolphin.position.x+=Math.sin(t*.8)*dt*1.2;this.dolphin.position.y=Math.max(-.3,Math.sin(t*3)*1.1);this.dolphin.rotation.set(Math.cos(t*3)*.3,Math.PI,0);const d=Math.hypot(s.x-this.dolphin.position.x,s.z-this.dolphin.position.z);if(d<13&&Math.hypot(s.vx,s.vz)>2)this.follow+=dt;if(this.follow>8){this.emit('find',{kind:'dolphin',amount:1});this.dolphinLife=0;}if(d>38||this.dolphinLife<=0){this.dolphin.visible=false;this.dolphinAt=this.time+65;}}
 this.vortex.rotation.y=-t*.8;this.vortexCooldown=Math.max(0,this.vortexCooldown-dt);const dx=s.x+25,dz=s.z+167,d=Math.hypot(dx,dz);if(d<5&&!this.vortexCooldown){s.vx+=(-dz-dx*.2)*dt*2;s.vz+=(dx-dz*.2)*dt*2;this.vortexCharge+=dt;if(this.vortexCharge>=10){this.emit('find',{kind:'whirlpool',amount:10});this.vortexCharge=0;this.vortexCooldown=30;}}else if(this.vortexCharge>0){if(this.vortexCharge>=1)this.emit('find',{kind:'whirlpool',amount:Math.floor(this.vortexCharge)});this.vortexCharge=0;this.vortexCooldown=30;}
 }
}
